<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>PSU-CAT Digital Exam</title><style>body{font:16px Arial;background:#eef3ff;color:#163365;margin:0}.shell{max-width:1050px;margin:auto;padding:25px}.card{background:#fff;border-radius:12px;padding:25px;margin:12px 0}.question{border-bottom:1px solid #ddd;padding:12px}.question label{margin-right:18px}button{background:#12469c;color:#fff;border:0;padding:12px 20px;border-radius:8px;cursor:pointer}.overlay{position:fixed;inset:0;background:#000;color:#fff;z-index:1000;display:none;align-items:center;justify-content:center;text-align:center}.warning{position:fixed;inset:0;background:#000a;z-index:1100;display:none;align-items:center;justify-content:center}.warning>div{background:#fff;padding:30px;border-radius:10px;max-width:420px}.warning button{margin-top:18px}</style></head><body><div class="shell"><div class="card"><h1>PSU-CAT Digital Exam</h1><p>{{ $applicant->full_name }} · {{ $applicant->application_number }}</p><p>Choose one answer for each item. Leaving the exam window or using blocked shortcuts records a security strike.</p><button id="fullscreen" type="button">Enter fullscreen</button></div><form id="exam" method="post" action="{{ route('admission.submit',$token) }}">@csrf<div class="card">@for($i=1;$i<=80;$i++)<div class="question"><strong>Item {{ $i }}</strong><div>@foreach(['A','B','C','D'] as $letter)<label><input type="radio" name="answers[{{ $i }}]" value="{{ $letter }}"> {{ $letter }}</label>@endforeach</div></div>@endfor</div><button type="submit">Submit exam</button></form></div><div id="blackout" class="overlay">Screen protected. Return to the exam to continue.</div><div id="warning" class="warning"><div><h2 id="warning-title"></h2><p id="warning-body"></p><button id="continue" type="button">Continue exam</button></div></div><script>
const form=document.getElementById('exam'), warning=document.getElementById('warning'), blackout=document.getElementById('blackout');let sending=false, strikes={{ (int)$applicant->strike_count }}, lastIncident=0;const strikeUrl=@json(route('admission.strike',$token));
function answers(){return Object.fromEntries(new FormData(form).entries().filter(([key])=>key.startsWith('answers[')).map(([key,value])=>[key.match(/\d+/)[0],value]))}
async function incident(type){if(sending||Date.now()-lastIncident<700)return;lastIncident=Date.now();const response=await fetch(strikeUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({incident_type:type,answers:answers()})});if(!response.ok)return;const state=await response.json();strikes=state.strikes;if(state.terminated){sending=true;location.replace(@json(route('admission.complete')));return}document.getElementById('warning-title').textContent='Security warning '+strikes+' of 3';document.getElementById('warning-body').textContent='Stay in the exam window. A third incident will submit your current answers.';warning.style.display='flex'}
history.pushState({exam:true},'',location.href);window.addEventListener('popstate',()=>{history.pushState({exam:true},'',location.href);incident('back_button')});
document.addEventListener('keydown',e=>{const print=e.key==='PrintScreen'||(e.ctrlKey&&e.key.toLowerCase()==='p')||(e.metaKey&&e.shiftKey&&e.key==='4');if(print){e.preventDefault();blackout.style.display='flex';incident(e.key==='PrintScreen'?'print_screen':'print')}});
window.addEventListener('blur',()=>{if(!sending){blackout.style.display='flex';incident('focus_loss')}});window.addEventListener('focus',()=>{blackout.style.display='none'});document.getElementById('continue').onclick=()=>warning.style.display='none';document.getElementById('fullscreen').onclick=()=>document.documentElement.requestFullscreen?.();form.addEventListener('submit',()=>sending=true);
</script></body></html>
